/**
 * Ensures the tables backing the schema above exist. This keeps all database
 * initialization encapsulated within this module so callers only need getDb().
 */
function initializeDb(sqlite: Database.Database) {
  sqlite.exec(`
    CREATE TABLE IF NOT EXISTS prompts (
      id TEXT PRIMARY KEY,
      created_at INTEGER NOT NULL DEFAULT CURRENT_TIMESTAMP,
      prompt TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS datasets (
      id TEXT PRIMARY KEY,
      tests TEXT,
      created_at INTEGER NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS evals (
      id TEXT PRIMARY KEY,
      created_at INTEGER NOT NULL DEFAULT CURRENT_TIMESTAMP,
      description TEXT,
      results TEXT NOT NULL,
      config TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS evals_to_prompts (
      eval_id TEXT NOT NULL REFERENCES evals(id),
      prompt_id TEXT NOT NULL REFERENCES prompts(id),
      PRIMARY KEY (eval_id, prompt_id)
    );
    CREATE TABLE IF NOT EXISTS evals_to_datasets (
      eval_id TEXT NOT NULL REFERENCES evals(id),
      dataset_id TEXT NOT NULL REFERENCES datasets(id),
      PRIMARY KEY (eval_id, dataset_id)
    );
  `);
}

export function getDb() {
  if (!dbInstance) {
    const sqlite = new Database(getDbPath());
    initializeDb(sqlite);
    dbInstance = drizzle(sqlite);
  }
  return dbInstance;
